code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    palette=None
    for r in range(h-1):
        vals=[v for v in grid[r] if v]
        if vals and vals==[v for v in grid[r+1] if v]: palette=vals; break
    if palette is None: raise ValueError("palette not found")
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]==1 and (r,c) not in seen:
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
         a,b=stack.pop(); comp.append((a,b))
         for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
          if 0<=x<h and 0<=y<w and grid[x][y]==1 and (x,y) not in seen: seen.add((x,y)); stack.append((x,y))
        comps.append(comp)
    pts=max(comps,key=len)
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    mask={(r-r0,c-c0) for r,c in pts}; sh=max(r for r,c in pts)-r0+1
    idx=palette.index(1); start=r0-idx*sh
    out=[[0]*w for _ in range(h)]
    for i,color in enumerate(palette):
     for dr,dc in mask:
      rr=start+i*sh+dr
      if 0<=rr<h: out[rr][c0+dc]=color
    return out
'''
